export const ZimmProductCardMedia = {
  parts: [
    'root',
    'scrollContainer',
    'slide',
    'image',
    'hoverSwapBase',
    'hoverSwapOverlay',
    'badge',
    'badgeLabel',
    'close',
    'carousel',
    'arrowButton',
    'indicatorWrapper',
  ],

  baseStyle: (): Record<string, SystemStyleObject> => ({
    root: {
      position: 'relative',
      width: '100%',
    },

    scrollContainer: {
      display: 'flex',
      width: '100%',
      overflowX: 'auto',
      scrollSnapType: 'x mandatory',
      // Safari touch scrolling needs this for scroll-snap to feel native — same precedent as
