    image: {
      display: 'block',
      width: '100%',
      height: '100%',
      objectFit: 'cover',
    },

    hoverSwapBase: {
      display: 'block',
      width: '100%',
      height: '100%',
      objectFit: 'cover',
      position: 'absolute',
      inset: 0,
      opacity: 1,
