      display: 'block',
      width: '100%',
      height: '100%',
      objectFit: 'cover',
      position: 'absolute',
      inset: 0,
      opacity: 0,
      transition: 'opacity var(--zimm-motion-duration-default) var(--zimm-motion-easing-fades)',
    },

    badge: {
      position: 'absolute',
      top: 0,
      left: 0,
