2	 * TEMPORARY, THROWAWAY DEMO — not intended to merge. See the PR this ships on for context: it
3	 * exists purely to show the shared ZimmProductCard component family (PR #85) live, against real
4	 * SFCC product data, from the homepage, via this repo's ephemeral MRT preview environment.
5	 *
6	 * Renders all 11 states ZimmProductCard's own Storybook story set already covers
7	 * (organisms/zimmProductCard/index.stories.tsx), reusing ONE real fetched product's data as the
8	 * shared base and overriding only the specific prop(s) each state needs — the same
9	 * `{...Default.args, <override>}` pattern that story file already uses, just with a real product
10	 * substituted for its hand-authored SVG fixture. Add-to-bag is fully real (the same
11	 * `addItemToNewOrExistingBasket` mutation the PDP uses); `onNotifyMe`/`onRemove` are demo-only
12	 * toasts, since no such mutation exists anywhere in this codebase to wire them to for real.
13	 *
14	 * Known, un-fixed gap: `ZimmProductCardContent`'s bag button has no loading-spinner slot at all
15	 * (only `isUnavailable` exists as a lever) — a slow add-to-bag request shows no in-button pending
16	 * state. Not fixed here; that would be scope creep onto a broadly-consumed shared component for a
17	 * throwaway demo page.
18	 */
19	import React, { useMemo, useState } from 'react';
20	import { useIntl } from 'react-intl';
21	import { Box, Stack, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
22	import Section from '@salesforce/retail-react-app/app/components/section';
23	import {
24	  useProductSearch,
25	  useShopperBasketsV2MutationHelper as useShopperBasketsMutationHelper,
26	} from '@salesforce/commerce-sdk-react';
27	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
28	import { HOME_SHOP_PRODUCTS_LIMIT } from '../../constants';
29	import { ZimmProductCard } from '../../components/ui-kits/organisms/zimmProductCard';
30	import type { ZimmProductCardProps } from '../../components/ui-kits/organisms/zimmProductCard';
31	import {
32	  pickDemoHit,
33	  selectLiveProductCardBase,
34	  buildSizeChipValues,
35	  type LiveDemoSourceHit,
36	} from './liveProductCardDemoMapper';
37	
38	/**
39	 * Page-local, unexported adaptation of organisms/zimmProductCard/index.stories.tsx's own
40	 * `LiveSizeSelectionCard` — same narrowing reasoning that file documents: attaching
41	 * `selectedSizeChipValue`/`onSizeChipSelect` onto an *unnarrowed* prop spread fails `tsc` on the
42	 * `home` union branch, so narrow via the `variation` discriminant first.
43	 */
44	const DemoSizeSelectableCard = (props: ZimmProductCardProps) => {
45	  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(() =>
46	    props.variation === 'plp' || props.variation === 'wishlist' ? props.selectedSizeChipValue : undefined,
47	  );
48	  const isSizeChipVariation = props.variation === 'plp' || props.variation === 'wishlist';
49	  const onSizeChipSelectFromProps = isSizeChipVariation ? props.onSizeChipSelect : undefined;
50	  const handleSizeChipSelect = (value: string) => {
51	    setSelectedSizeChipValue(value);
52	    onSizeChipSelectFromProps?.(value);
53	  };
54	  const propsWithLiveSelection: ZimmProductCardProps = isSizeChipVariation
55	    ? { ...props, selectedSizeChipValue, onSizeChipSelect: handleSizeChipSelect }
56	    : props;
57	  return <ZimmProductCard {...propsWithLiveSelection} />;
58	};
59	
60	export const LiveProductCardDemoSection = () => {
61	  const intl = useIntl();
62	  const showToast = useToast();
63	  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();
64	
65	  const {
66	    data: productSearchResult,
