68	    isError: isSearchError,
69	    error: searchError,
70	  } = useProductSearch({
71	    parameters: {
72	      // Confirmed live (2026-09-05): HOME_SHOP_PRODUCTS_CATEGORY_ID ('newarrivals') is a generic
73	      // base-template sample category with zero real hits in Zimmermann's actual catalog -- the
74	      // existing "Shop Products" section elsewhere on this page has this exact same latent gap.
75	      // A free-text query is independent of category taxonomy entirely, so it doesn't matter that
76	      // the real category structure is unknown/undocumented -- confirmed more robust for a
77	      // throwaway demo than guessing at a real cgid.
78	      q: 'dress',
79	      // `htype` is a `refine` VALUE, not its own top-level param -- confirmed against
80	      // commerce-sdk-isomorphic's real ProductSearchParams, which has no `htype` field at all.
81	      // A bogus top-level `htype` key silently type-checks (the SDK's params type intersects
82	      // with a permissive QueryParameters) but does nothing at runtime, so this was searching
83	      // unscoped by hit type.
84	      refine: 'htype=master',
85	      expand: ['promotions', 'variations', 'prices', 'images', 'custom_properties'],
86	      // Per the SDK's own doc comment: if `allImages` isn't passed at all, `imageGroups` is
87	      // omitted from the response outright, regardless of `expand` including 'images' -- this,
88	      // not the viewType filter, was the real reason cards rendered with no image.
89	      allImages: true,
90	      perPricebook: true,
91	      allVariationProperties: true,
92	      limit: HOME_SHOP_PRODUCTS_LIMIT,
