1	/*
2	 * Copyright (c) 2022, Salesforce, Inc.
3	 * All rights reserved.
4	 * SPDX-License-Identifier: BSD-3-Clause
5	 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
6	 */
7	
8	import React, { useEffect, useRef, useState } from 'react';
9	import { useIntl } from 'react-intl';
10	import { Button } from '@salesforce/retail-react-app/app/components/shared/ui';
11	import ProductScroller from '@salesforce/retail-react-app/app/components/product-scroller';
12	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
13	import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud';
14	import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
15	import useIntersectionObserver from '@salesforce/retail-react-app/app/hooks/use-intersection-observer';
16	import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
17	
18	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
19	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
20	import {
21	  API_ERROR_MESSAGE,
22	  TOAST_ACTION_VIEW_WISHLIST,
23	  TOAST_MESSAGE_ADDED_TO_WISHLIST,
24	  TOAST_MESSAGE_REMOVED_FROM_WISHLIST,
25	} from '@salesforce/retail-react-app/app/constants';
26	import { useShopperCustomersMutation } from '@salesforce/commerce-sdk-react';
27	
28	// Types
29	import type { ShopperCustomersTypes } from 'commerce-sdk-isomorphic';
30	
31	/**
32	 * Props for `RecommendedProducts`, ported 1:1 from the base file's `propTypes`
33	 * block (node_modules/@salesforce/retail-react-app/app/components/recommended-products/index.jsx).
34	 * `@salesforce/retail-react-app` ships no types of its own (see
35	 * overrides/app/types/vendor.d.ts's `@salesforce/retail-react-app/*` catch-all),
36	 * so the index signature below stands in for the untyped `...props` passthrough
37	 * to `ProductScroller` — real base call sites forward arbitrary Chakra style
38	 * props this way (e.g. base cart/index.jsx's `mx={{...}}` on this same component).
39	 */
40	type RecommendedProductsProps = {
41	  /* The title to appear above the product scroller */
42	  title?: React.ReactNode;
43	
44	  /* The zone to request */
45	  zone?: string;
46	
47	  /* The recommender to request */
48	  recommender?: string;
49	
50	  /* The products to use for recommendation context */
51	  products?: readonly Record<string, unknown>[];
52	
53	  /* Callback to determine if the component should fetch results */
54	  shouldFetch?: () => boolean;
55	
56	  [key: string]: unknown;
57	};
58	
59	/**
60	 * The shape of one item in `useEinstein()`'s `recommendations.recs` array.
61	 * Only the two fields this file actually reads are modelled — the real object
62	 * is a runtime merge of the raw Einstein rec and a fetched Product (see
63	 * node_modules/@salesforce/retail-react-app/app/hooks/use-einstein.js's
64	 * `fetchRecProductDetails`, lines 465-520: `ids` is read off `rec.id` at line
65	 * 466 before any merge, so `id` is always present; `productId: rec.id` is set
66	 * only on the successful-merge path at line 502, so it is modelled optional —
67	 * the function falls back to returning the raw, un-merged `reco` at line 519
68	 * if its own fetch throws). `useEinstein`/`ProductScroller` are both untyped
69	 * (see `RecommendedProductsProps`'s comment above), so this file has no other
70	 * source of truth for the shape than that base hook's own implementation.
71	 */
72	type EinsteinRecommendationItem = {
73	  id: string;
74	  productId?: string;
75	};
76	
77	/**
78	 * A component for fetching and rendering product recommendations from the Einstein API
79	 * by a zone or a recommender name.
80	 */
81	const RecommendedProducts = ({
82	  zone,
83	  recommender,
84	  products,
85	  title,
86	  shouldFetch,
87	  ...props
88	}: RecommendedProductsProps): React.ReactElement | null => {
89	  console.log('[overrides] recommended-products/index.tsx');
90	  const { isLoading, recommendations, getZoneRecommendations, getRecommendations, sendClickReco, sendViewReco } =
91	    useEinstein();
92	  const { data: customer } = useCurrentCustomer();
93	  const { customerId } = customer;
94	  const { data: wishlist } = useWishList();
95	  const dataCloud = useDataCloud();
96	
97	  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
98	  const deleteCustomerProductListItem = useShopperCustomersMutation('deleteCustomerProductListItem');
99	  const toast = useToast();
100	  const navigate = useNavigation();
101	  // react-intl returns already-bound methods, so destructuring `formatMessage` cannot unbind
102	  // anything — the rule cannot see that. Same precedent/justification as
103	  // overrides/app/pages/product-detail/index.tsx's identical destructure of useIntl().
104	  // eslint-disable-next-line @typescript-eslint/unbound-method
105	  const { formatMessage } = useIntl();
106	
107	  const ref = useRef();
108	  const isOnScreen = useIntersectionObserver(ref, { useOnce: true });
109	  const [_products, setProducts] = useState(products);
110	
111	  useEffect(() => {
112	    // Check if the component should fetch results or not. This is useful
113	    // when you are still waiting on additional data, like `products`.
114	    if (typeof shouldFetch === 'function' && !shouldFetch()) {
115	      return;
116	    }
117	
118	    // Fetch either zone or recommender, but not both. If a zone and recommender
119	    // name are both provided, `zone` takes precendence.
120	    if (zone) {
121	      getZoneRecommendations(zone, _products);
122	      return;
123	    }
124	    if (recommender) {
125	      getRecommendations(recommender, _products);
126	      return;
127	    }
128	  }, [zone, recommender, _products]);
129	
130	  useEffect(() => {
131	    // This is an optimization that eliminates superfluous rerenders/fetching by
132	    // keeping a copy of the `products` array prop in state for shallow comparison.
133	    if (!Array.isArray(products)) {
134	      return;
135	    }
136	    if (products.length !== _products?.length || !products.every((val, index) => val === _products?.[index])) {
137	      setProducts(products);
138	    }
139	  }, [products]);
140	
141	  useEffect(() => {
142	    if (isOnScreen && recommendations?.recs) {
143	      sendViewReco(
144	        {
145	          recommenderName: recommendations.recommenderName,
146	          __recoUUID: recommendations.recoUUID,
147	        },
148	        recommendations.recs.map((rec: EinsteinRecommendationItem) => ({ id: rec.id })),
149	      );
150	      dataCloud.sendViewRecommendations(
151	        {
152	          recommenderName: recommendations.recommenderName,
153	          __recoUUID: recommendations.recoUUID,
154	        },
155	        recommendations.recs.map((rec: EinsteinRecommendationItem) => ({ id: rec.id })),
156	      );
157	    }
158	  }, [isOnScreen, recommendations]);
159	
160	  // The component should remove itself altogether if it has no recommendations
161	  // and we aren't loading any.
162	  if (!isLoading && (!recommendations || recommendations.length < 1)) {
163	    return null;
164	  }
165	
166	  // TODO: DRY this handler when intl provider is available globally
167	  const addItemToWishlist = async (product: EinsteinRecommendationItem): Promise<void> => {
168	    try {
169	      if (!wishlist || !customerId) {
170	        return;
171	      }
172	      await createCustomerProductListItem.mutateAsync({
173	        parameters: {
174	          listId: wishlist.id,
175	          customerId,
176	        },
177	        body: {
178	          quantity: 1,
179	          productId: product.productId,
180	          public: false,
181	          priority: 1,
182	          type: 'product',
183	        },
184	      });
185	
186	      toast({
187	        title: formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
188	        status: 'success',
189	        action: (
190	          // it would be better if we could use <Button as={Link}>
191	          // but unfortunately the Link component is not compatible
192	          // with Chakra Toast, since the ToastManager is rendered via portal
193	          // and the toast doesn't have access to intl provider, which is a
194	          // requirement of the Link component.
195	          <Button variant="link" onClick={() => navigate('/account/wishlist')}>
196	            {formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
197	          </Button>
198	        ),
199	      });
200	    } catch {
201	      toast({
202	        title: formatMessage(API_ERROR_MESSAGE),
203	        status: 'error',
204	      });
205	    }
206	  };
207	
208	  const removeItemFromWishlist = async (product: EinsteinRecommendationItem): Promise<void> => {
209	    try {
210	      const wishlistItem = wishlist?.customerProductListItems?.find(
211	        (item: ShopperCustomersTypes.CustomerProductListItem) => item.productId === product.productId,
212	      );
213	      if (!wishlistItem || !wishlist || !customerId) {
214	        return;
215	      }
216	      await deleteCustomerProductListItem.mutateAsync({
217	        parameters: {
218	          customerId,
219	          itemId: wishlistItem.id,
220	          listId: wishlist.id,
221	        },
222	      });
223	      toast({
224	        title: formatMessage(TOAST_MESSAGE_REMOVED_FROM_WISHLIST),
225	        status: 'success',
226	        id: product.productId,
227	      });
228	    } catch {
229	      toast({
230	        title: formatMessage(API_ERROR_MESSAGE),
231	        status: 'error',
232	      });
233	    }
234	  };
235	
236	  return (
237	    <ProductScroller
238	      ref={ref}
239	      title={title || recommendations?.displayMessage}
240	      products={recommendations.recs}
241	      isLoading={isLoading}
242	      productTileProps={(product: EinsteinRecommendationItem) => ({
243	        onClick: () => {
244	          sendClickReco(
245	            {
246	              recommenderName: recommendations.recommenderName,
247	              __recoUUID: recommendations.recoUUID,
248	            },
249	            product,
250	          );
251	        },
252	        enableFavourite: true,
253	        isFavourite: wishlist?.customerProductListItems?.some(
254	          (item: ShopperCustomersTypes.CustomerProductListItem) => item.productId === product?.productId,
255	        ),
256	        onFavouriteToggle: (toBeFavourite: boolean) => {
257	          const action = toBeFavourite ? addItemToWishlist : removeItemFromWishlist;
258	          return action(product);
259	        },
260	      })}
261	      {...props}
262	    />
263	  );
264	};
265	
266	export default RecommendedProducts;
267

