            if (
                !hydrated &&
                hydrateOn !== 'off' &&
                (!context || context?.hydrated) &&
                ref.current &&
                !ref.current?.firstElementChild &&
                !clientOnly
            ) {
                // No actual SSR Content or rendering after CSR navigation --> hydrate
                hydrate()
            }
        })

        useEffect(() => {
            if (
                hydrated ||
                hydrateOn === 'off' ||
                (context && !context?.hydrated) ||
                !ref.current ||
                (!ref.current?.firstElementChild && !ssr && !clientOnly)
