61	/**
62	 * Fix I (SFCC-236, click-passthrough): `vi.hoisted` again, same reasoning as
63	 * `capturedOrganismStyleProps` above — this mock function is referenced from inside the
64	 * `vi.mock('react-router-dom', ...)` factory below, which Vitest hoists above this file's own
65	 * top-level `const`s, so a plain `const mockHistoryPush = vi.fn()` here would hit the same TDZ
66	 * error `vi.hoisted` exists to avoid.
67	 */
68	const { mockHistoryPush } = vi.hoisted(() => ({
69	  mockHistoryPush: vi.fn(),
70	}));
