93	        arrowButton: {},
94	        indicatorWrapper: {},
95	        // ZimmSlideIndicator.
96	        dot: {},
97	        // ZimmProductCardContent.
98	        nameRow: {},
99	        nameLink: {},
100	        bagWrapper: {},
101	        bagButton: {},
102	        attributesRow: {},
103	        colourText: {},
104	        sizeText: {},
105	        priceWrapper: {},
