177	/**
178	 * Module-scope (not describe-block-local) so both the "real recipe assertions" describe block
179	 * below AND the Fix 1 / Fix 2 (Scorer rework round 1) DOM-level proof blocks further down can
180	 * share one definition rather than each hand-duplicating the same literal selector strings.
181	 */
182	const STRETCH_KEY = `[data-card-slot="${CARD_SLOT.content}"] a::after`;
183	const CLOSE_LIFT_KEY = `[data-card-slot="${CARD_SLOT.close}"]`;
184	const CAROUSEL_LIFT_KEY = `[data-card-slot="${CARD_SLOT.carousel}"]`;
185	// Fix I — the media/gallery scroll region's own lift key (zimmProductCard.css.ts docblock point
186	// 2's new bullet), built the same way as CLOSE_LIFT_KEY/CAROUSEL_LIFT_KEY above.
187	const MEDIA_LIFT_KEY = `[data-card-slot="${CARD_SLOT.media}"]`;
188	// Behavioural fix: the carousel arrow reveal (docblock point 6) — unlike every other reveal key
189	// below, these two are unconditional (no gating flag), so they're built straight off
190	// CAROUSEL_LIFT_KEY rather than a nested `[data-card-slot="content"] ...` path — the carousel
191	// wrapper is a direct child of Media's own root, a sibling of `content`, not nested under it.
192	const HOVER_CAROUSEL_KEY = `&:hover ${CAROUSEL_LIFT_KEY}`;
193	const FOCUS_VISIBLE_CAROUSEL_KEY = `&:has(:focus-visible) ${CAROUSEL_LIFT_KEY}`;
194	// Fix J belt-and-braces (SFCC-236) — the carousel wrapper's own arrow-button pointerEvents pair
195	// (see zimmProductCard.css.ts docblock point 6's own Fix J note): unconditional 'none' by
196	// default, 'auto' only inside the same two revealed selectors above.
197	const CAROUSEL_BUTTON_LIFT_KEY = `${CAROUSEL_LIFT_KEY} button`;
198	const HOVER_CAROUSEL_BUTTON_KEY = `&:hover ${CAROUSEL_BUTTON_LIFT_KEY}`;
199	const FOCUS_VISIBLE_CAROUSEL_BUTTON_KEY = `&:has(:focus-visible) ${CAROUSEL_BUTTON_LIFT_KEY}`;
200	const CONTENT_LIFT_KEY = `[data-card-slot="${CARD_SLOT.content}"] button`;
201	const PRICE_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.price}"]`;
202	const SIZE_CHIPS_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.sizeChips}"]`;
203	const HOVER_PRICE_KEY = `&:hover ${PRICE_KEY}`;
