206	// above — see this file's own docblock note on the compound-selector vs separate-key idiom
207	// question, resolved by reading zimmSearchInput.css.ts and globalStyles.ts's zimmFormRow/
208	// zimmFormRowInverse: both use a separate sibling key (`_focusWithin` alongside `_hover`), never
209	// a comma-joined compound selector. This file already uses raw selector strings (not Chakra's
210	// `_hover`/`_focusWithin` shorthand props) because the hover rules need a descendant-combinator
211	// path baked into the selector itself, so the equivalent here is a separate `'&:has(:focus-visible) ...'`
212	// string key alongside the existing `'&:hover ...'` key, not a merged `'&:hover, &:has(:focus-visible) ...'`
213	// selector.
214	const FOCUS_VISIBLE_PRICE_KEY = `&:has(:focus-visible) ${PRICE_KEY}`;
215	const FOCUS_VISIBLE_SIZE_CHIPS_KEY = `&:has(:focus-visible) ${SIZE_CHIPS_KEY}`;
216	// Fix C: notify-me's own reveal-key trio, all three living INSIDE the HOVER_CAPABLE_QUERY block
217	// (see zimmProductCard.css.ts docblock point 4 for why this is the opposite structure from price/
