/**
 * Maps one Recently Viewed recommendation onto the subset of `ZimmProductCard` props the
 * `recentlyViewed` variation (SFCC-83) actually renders.
 *
 * Input is exactly what `use-einstein.js`'s `fetchRecProductDetails` produces (search that name
 * in `node_modules/@salesforce/retail-react-app/app/hooks/use-einstein.js`): an Einstein rec
 * merged with its matching Commerce API product, fetched via `getProducts` with `expand:
 * ['availability', 'links', 'promotions', 'options', 'images', 'prices', 'variations']` —
 * `{...rec, ...product, productId: rec.id, image: {disBaseLink: rec.imageUrl, alt:
 * rec.productName}}`.
 *
 * Modelled on `overrides/app/pages/product-detail/productInfo.ts` — no React/react-intl import,
 * `formatPrice` injected as a parameter so this module stays independently testable — and on the
 * general shape of `liveProductCardDemoMapper.ts` (`feature/zimmproductcard-live-demo`, not this
 * branch — read for its approach, not imported). Unlike that demo mapper, this is a production
 * path: real `commerce-sdk-isomorphic` SDK types are used wherever they exist (AGENTS.md > Type
 * Definitions), and only the two fields the SDK doesn't export (`productId`, the flat Einstein
 * `image`) are hand-rolled, each with its own why-comment below.
 *
 * Deliberately narrow scope, stated here rather than left as a silent gap: this mapper only ever
 * returns `currentPrice` (an active selling price). It does not attempt was/now sale-price
 * detection (`originalPrice`) — that needs `getPriceData`-style pricebook logic
 * (`productInfo.ts`'s own `PdpSourcePrice`) that this merged Einstein shape has no equivalent of,
 * and the `recentlyViewed` variation renders no price at all today (see
 * `zimmProductCard/index.tsx`'s `recentlyViewed` `VARIATION_CONFIG` row — `showContent: false`).
 * Mapping `currentPrice` anyway costs nothing and means a future consumer of this same mapper
 * (e.g. a variation that does render price) isn't blocked on this file being revisited.
 */
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type { ZimmProductCardBaseProps, ZimmProductCardImage } from '../components/ui-kits/organisms/zimmProductCard';

/**
 * The real Commerce API `Product` (`commerce-sdk-isomorphic`'s own `ShopperProductsTypes.Product`
 * — not hand-rolled), plus the two fields `fetchRecProductDetails` bolts on that have no SDK
 * equivalent:
 */
export type RecentlyViewedProduct = ShopperProductsTypes.Product & {
  /** Set by `fetchRecProductDetails` to `rec.id`. Guaranteed present and equal to `Product.id`
   *  for every entry that function produces (it already filters out any rec with no matching
   *  product before this shape exists at all) — read this rather than `.id` only because it's
   *  the field the real runtime hook explicitly produces this way. */
  productId: string;
  /** The same function's own quick single-reference image (Einstein's own `rec.imageUrl`/
   *  `rec.productName`), distinct from the full product's own `imageGroups` array below — used
   *  as a fallback only when `imageGroups` filtering comes up empty. See `selectPrimaryImage`. */
  image?: { disBaseLink?: string; alt?: string };
};

/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl,
 *  mirroring `productInfo.ts`'s own `FormatPrice` shape. */
export type FormatPrice = (amount: number, currency: string) => string;

/**
 * The subset of `ZimmProductCardBaseProps` this mapper populates. Deliberately excludes
 * `headingLevel` and `variation` — both are render-context decisions belonging to the container
 * step that maps recs through this mapper and renders the rail (SFCC-83's A6 step), which supplies
 * `headingLevel` uniformly for every card and adds `variation: 'recentlyViewed'` itself when
 * spreading this output into `<ZimmProductCard>` — the rail organism itself (A5) takes already-full
 * `ZimmProductCardProps` objects, so variation must already be set before it sees them. A pure data
 * mapper choosing a heading level would conflate a data concern with a layout one. Also excludes `hoverImage`/`images` — this
 * mapper only ever returns one image (`primaryImage`); see `selectPrimaryImage`'s own docblock
 * for why.
 */
export type RecentlyViewedCard = Pick<
  ZimmProductCardBaseProps,
  'id' | 'href' | 'name' | 'primaryImage' | 'currentPrice'
>;

/** The correctly-sized product image view, per AGENTS.md's image-sizing guidance: never serve an
 *  arbitrary-sized image at thumbnail size. Named rather than inlined per conventions.md's
 *  no-magic-strings rule — this is a real, semantic SFCC image `viewType` key. */
const MEDIUM_VIEW_TYPE = 'medium';

/**
 * Resolves the one image this mapper ever returns. `hoverImage`/`images` are never populated —
 * SFCC-83 AC 3 asks for "the product's index image" (singular), and the `recentlyViewed`
 * variation renders neither a hover-swap nor a gallery (see `zimmProductCard/index.tsx`'s
 * `recentlyViewed` row: `showHoverImageSwap: false`, and its render branch never forwards
 * `images` at all).
 *
 * Prefers `filterImageGroups` at `viewType: 'medium'` (a real, correctly-sized product image) —
 * `variationValues` is deliberately empty: a Recently Viewed rec is already one specific product,
 * not a search hit needing a variant pick the way `liveProductCardDemoMapper.ts`'s own
 * `resolveDemoVariant` handles, so that logic does not apply here. Falls back to Einstein's own
 * flat `image` field only when that filtering produces nothing usable — see
 * `RecentlyViewedProduct.image`'s own comment for what that field is.
 *
 * @returns `null` when neither source has a usable `src`. `ZimmProductCardMediaImage.alt` is
 *   required and non-empty, so there is no safe placeholder card to build without a real image —
 *   a card with an invented placeholder `src` would need an asset this codebase has no confirmed
 *   token or precedent for, so "no usable image" is treated the same as "no usable name" in
 *   `selectRecentlyViewedCard` below: a hard gate that yields no card at all. Returning `null`
 *   here is the only option that structurally cannot violate the non-empty-`alt` contract, since
 *   there is no returned object for `alt` to be empty on.
 */
const selectPrimaryImage = (product: RecentlyViewedProduct, productName: string): ZimmProductCardImage | null => {
  const filteredGroups = filterImageGroups(product.imageGroups ?? [], {
    viewType: MEDIUM_VIEW_TYPE,
    variationValues: {},
  }) as ShopperProductsTypes.ImageGroup[];
  const [groupImage] = filteredGroups[0]?.images ?? [];

  const src = groupImage ? groupImage.disBaseLink || groupImage.link : product.image?.disBaseLink;
  if (!src) return null;

  // ZimmProductCardMediaImage.alt is required and non-empty (unlike base ProductTile's
  // decorative alt: '' convention) — mirrors liveProductCardDemoMapper.ts's own fallback exactly.
  const alt = (groupImage ? groupImage.alt : product.image?.alt)?.trim() || productName;
  return { src, alt };
};

/**
 * @param product - The merged Einstein rec + Commerce API product `fetchRecProductDetails`
 *   produces, or `undefined`/`null` while that data is not yet available.
 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
 * @returns Props for the `recentlyViewed` `ZimmProductCard` variation, or `null` when the rec has
 *   no usable name or no usable image — never a broken card, never a throw.
 */
export const selectRecentlyViewedCard = (
  product: RecentlyViewedProduct | undefined | null,
  formatPrice: FormatPrice,
): RecentlyViewedCard | null => {
  if (!product?.name) return null;

  const primaryImage = selectPrimaryImage(product, product.name);
  if (!primaryImage) return null;

  return {
    // Reads productId, not the SDK Product's own `id` — see RecentlyViewedProduct.productId's
    // own comment for why (guaranteed equal in practice, but productId is the field the real
    // runtime hook explicitly produces this way).
    id: product.productId,
    href: productUrlBuilder({ id: product.productId }),
    name: product.name,
    primaryImage,
    // No hardcoded fallback currency — if either is absent, skip formatting rather than guess,
    // matching productInfo.ts's own "no hardcoded fallback currency" comment.
    currentPrice:
      typeof product.price === 'number' && product.currency ? formatPrice(product.price, product.currency) : undefined,
  };
};

/**
 * Ties the merged Einstein-rec/Commerce-API shape to the rendered `ZimmProductCard` props, the
 * same doctrine `productInfo.test.ts` documents as "G1": every assertion below uses a value
 * unique to its own field (see `FULL` below — `id` is deliberately different from `productId`,
 * and the 'large' image group's `alt` is deliberately a value that must never be picked) so a
 * mapping that reads the wrong key fails rather than coincidentally matching.
 */
import { describe, expect, test, vi } from 'vitest';
import { selectRecentlyViewedCard, type FormatPrice, type RecentlyViewedProduct } from './recentlyViewedCard';

const formatPrice: FormatPrice = (amount, currency) => `${currency} ${amount.toFixed(2)}`;

// `id` is deliberately NOT equal to `productId` — a real matched rec always has them equal, but
// diverging them here means every test using FULL would fail loudly if the mapper ever read the
// wrong one (see RecentlyViewedProduct.productId's own comment on why productId is correct).
const FULL: RecentlyViewedProduct = {
  id: 'SDK-PRODUCT-ID-MUST-NOT-BE-USED',
  productId: 'REC-PRODUCT-ID-0001',
  name: 'Natura Mini Dress',
  price: 895,
  currency: 'AUD',
  imageGroups: [
    {
      viewType: 'medium',
      images: [
        {
          link: 'https://example.test/medium/natura-mini-dress-link.jpg',
          disBaseLink: 'https://cdn.example.test/medium/natura-mini-dress.jpg',
          alt: 'Natura Mini Dress, Ivory',
        },
      ],
    },
    {
      // Wrong viewType — must never be picked. If it is, this test's alt assertion fails.
      viewType: 'large',
      images: [
        { link: 'https://example.test/large/natura-mini-dress.jpg', alt: 'WRONG VIEWTYPE — MUST NOT BE PICKED' },
      ],
    },
  ],
  image: {
    disBaseLink: 'https://cdn.example.test/einstein/natura-mini-dress.jpg',
    alt: 'EINSTEIN FALLBACK — MUST NOT BE PICKED WHEN imageGroups HAS A USABLE MEDIUM IMAGE',
  },
};

describe('selectRecentlyViewedCard — happy path', () => {
  test('maps every field to its correct prop, preferring the medium imageGroups image over the flat Einstein fallback', () => {
    expect(selectRecentlyViewedCard(FULL, formatPrice)).toEqual({
      id: 'REC-PRODUCT-ID-0001',
      href: '/product/REC-PRODUCT-ID-0001',
      name: 'Natura Mini Dress',
      primaryImage: {
        src: 'https://cdn.example.test/medium/natura-mini-dress.jpg',
        alt: 'Natura Mini Dress, Ivory',
      },
      currentPrice: 'AUD 895.00',
    });
  });

  test('id and href are built from productId, not the SDK Product.id field', () => {
    const card = selectRecentlyViewedCard(FULL, formatPrice);
    expect(card?.id).toBe('REC-PRODUCT-ID-0001');
    expect(card?.id).not.toBe(FULL.id);
  });

  test('href is a bare /product/{id} path — no site-prefix of its own', () => {
    const card = selectRecentlyViewedCard(FULL, formatPrice);
    expect(card?.href).toBe('/product/REC-PRODUCT-ID-0001');
    expect(card?.href).not.toMatch(/^https?:\/\//);
  });

  test('omits headingLevel, variation, hoverImage and images entirely — not just empty', () => {
    const card = selectRecentlyViewedCard(FULL, formatPrice) as object | null;
    expect(card).not.toBeNull();
    expect(card).not.toHaveProperty('headingLevel');
    expect(card).not.toHaveProperty('variation');
    expect(card).not.toHaveProperty('hoverImage');
    expect(card).not.toHaveProperty('images');
  });
});

describe('selectRecentlyViewedCard — no usable name, no card', () => {
  test('returns null when name is missing', () => {
    expect(selectRecentlyViewedCard({ ...FULL, name: undefined }, formatPrice)).toBeNull();
  });

  test('returns null when name is an empty string', () => {
    expect(selectRecentlyViewedCard({ ...FULL, name: '' }, formatPrice)).toBeNull();
  });

  test('returns null for a nullish product (still loading)', () => {
    expect(selectRecentlyViewedCard(undefined, formatPrice)).toBeNull();
    expect(selectRecentlyViewedCard(null, formatPrice)).toBeNull();
  });
});

describe('selectRecentlyViewedCard — no usable image, no card', () => {
  // Decision (documented, not silently made): "no usable image at all" is treated the same as
  // "no usable name" — a hard null gate — rather than a placeholder-image card. A placeholder
  // would need an asset/src this codebase has no confirmed token for, and null is the only
  // choice that structurally cannot violate ZimmProductCardMediaImage.alt's required-non-empty
  // contract (there is no returned object for alt to be empty on). See selectPrimaryImage's own
  // docblock in recentlyViewedCard.ts for the same note at the point of the decision.
  test('returns null when imageGroups is absent and there is no fallback image either', () => {
    expect(selectRecentlyViewedCard({ ...FULL, imageGroups: undefined, image: undefined }, formatPrice)).toBeNull();
  });

  test('returns null when imageGroups is an empty array and there is no fallback image', () => {
    expect(selectRecentlyViewedCard({ ...FULL, imageGroups: [], image: undefined }, formatPrice)).toBeNull();
  });

  test('returns null when imageGroups filtering matches nothing (no medium viewType) and there is no fallback image', () => {
    const noMediumGroup: RecentlyViewedProduct = {
      ...FULL,
      imageGroups: [{ viewType: 'large', images: [{ link: 'https://example.test/large-only.jpg' }] }],
      image: undefined,
    };
    expect(selectRecentlyViewedCard(noMediumGroup, formatPrice)).toBeNull();
  });
});

describe('selectRecentlyViewedCard — disBaseLink/alt fallbacks within a selected imageGroups image', () => {
  // Distinct from the "flat Einstein image field" block below: every fixture that reaches this
  // branch elsewhere in this file happens to populate both disBaseLink and alt on the selected
  // medium image, so the fallback preference within that branch was never isolated on its own.
  test('falls back to link when the selected medium image has no disBaseLink', () => {
    const linkOnlyMedium: RecentlyViewedProduct = {
      ...FULL,
      imageGroups: [
        {
          viewType: 'medium',
          images: [{ link: 'https://example.test/medium/link-only.jpg', alt: 'Natura Mini Dress, link-only' }],
        },
      ],
    };
    const card = selectRecentlyViewedCard(linkOnlyMedium, formatPrice);
    expect(card?.primaryImage.src).toBe('https://example.test/medium/link-only.jpg');
  });

  test('falls back to the product name for alt when the selected medium image carries no alt of its own', () => {
    const noAltMedium: RecentlyViewedProduct = {
      ...FULL,
      imageGroups: [
        {
          viewType: 'medium',
          images: [
            {
              link: 'https://example.test/medium/no-alt.jpg',
              disBaseLink: 'https://cdn.example.test/medium/no-alt.jpg',
            },
          ],
        },
      ],
    };
    const card = selectRecentlyViewedCard(noAltMedium, formatPrice);
    expect(card?.primaryImage.alt).toBe('Natura Mini Dress');
  });
});

describe('selectRecentlyViewedCard — fallback to the flat Einstein image field', () => {
  test('uses image.disBaseLink as the src when imageGroups is absent entirely', () => {
    const card = selectRecentlyViewedCard({ ...FULL, imageGroups: undefined }, formatPrice);
    expect(card?.primaryImage).toEqual({
      src: 'https://cdn.example.test/einstein/natura-mini-dress.jpg',
      alt: 'EINSTEIN FALLBACK — MUST NOT BE PICKED WHEN imageGroups HAS A USABLE MEDIUM IMAGE',
    });
  });

  test('falls back to the product name for alt when the flat image field carries no alt of its own', () => {
    const card = selectRecentlyViewedCard(
      { ...FULL, imageGroups: undefined, image: { disBaseLink: FULL.image?.disBaseLink, alt: undefined } },
      formatPrice,
    );
    expect(card?.primaryImage.alt).toBe('Natura Mini Dress');
  });
});

describe('selectRecentlyViewedCard — price without a paired currency (no guessed currency)', () => {
  test('currentPrice is undefined when currency is missing, and formatPrice is never called', () => {
    const spy = vi.fn(formatPrice);
    const card = selectRecentlyViewedCard({ ...FULL, currency: undefined }, spy);
    expect(card?.currentPrice).toBeUndefined();
    expect(spy).not.toHaveBeenCalled();
  });

  test('currentPrice is undefined when price is missing, and formatPrice is never called', () => {
    const spy = vi.fn(formatPrice);
    const card = selectRecentlyViewedCard({ ...FULL, price: undefined }, spy);
    expect(card?.currentPrice).toBeUndefined();
    expect(spy).not.toHaveBeenCalled();
  });

  test('calls the injected formatter exactly once, with the real price and currency, when both are present', () => {
    const spy = vi.fn(formatPrice);
    selectRecentlyViewedCard(FULL, spy);
    expect(spy).toHaveBeenCalledOnce();
    expect(spy).toHaveBeenCalledWith(895, 'AUD');
  });
});

/**
 * Maps a Commerce API product onto the props the PDP's static-information components take.
 *
 * Extracted from the page so the mapping is unit-testable on its own. Nothing else on the PDP
 * ties an external field name to a rendered prop, and a mis-keyed field here does not fail
 * loudly: it falls through to `undefined`, the component returns `null`, and the page renders
 * a plausible-looking product with one line quietly missing. Neither a Storybook `play`
 * (which supplies its own props) nor an axe run can see that.
 */

/*
 * The Commerce SDK's `Product` type does not carry Zimmermann's `c_*` custom attributes, and
 * `@salesforce/retail-react-app` ships no types at all. This is the narrow shape this mapping
 * actually reads — everything optional, because every one of these fields can be absent on a
 * real catalogue product.
 */
/**
 * Shape of `c_tabDescription`/`c_tabDetails` — a rich-text attribute authored with both a
 * rendered `markup` (HTML, same shape as `longDescription`) and its plain-text `source`. Only
 * `markup` is read below, matching how every other rich-text field on this page is consumed
 * (through `app/utils/richText`'s HTML parser, not the plain-text form).
 */
export type SfccRichTextAttribute = {
  markup?: string;
  source?: string;
};

export type PdpSourceProduct = {
  id?: string;
  name?: string;
  longDescription?: string;
  /** Master product reference. Present on a variant; absent on a standard product. */
  master?: { masterId?: string };
  /** Zimmermann custom attribute holding the model's measurements and worn size. */
  c_modelFit?: string;
  /** Zimmermann custom attribute holding the product's care instructions, authored in Business
   *  Manager with the same markup shape as `longDescription` (see `app/utils/richText`). */
  c_careInstructions?: string;
  /** Colour code (e.g. "GVSCP") — not a display name. */
  c_color?: string;
  c_colourId?: string;
  /** EU Environmental Qualities content — SFCC-266's data source (MuleSoft/AP21), not this
   *  page's own concern yet; mapped here so that tab has it ready when it's built. */
  c_environmentalNotes?: string;
  c_fabricComposition?: string;
  /** Customs/tariff Harmonized System code — not a PDP display field. */
  c_hsCode?: string;
  /** SFCC-102's Size & Fit content, if/when that tab moves off Contentful onto this attribute —
   *  see the plan doc's note that Size & Fit was assumed Contentful-managed; not wired into
   *  DetailsAndCareContent or the Size & Fit tab yet, pending that confirmation. */
  c_sizeFit?: string;
  c_styleId?: string;
  c_styleNumber?: string;
  c_stylingNotes?: string;
  c_tabDescription?: SfccRichTextAttribute;
  c_tabDetails?: SfccRichTextAttribute;
};

/** The subset of `getPriceData`'s result this mapping needs. */
export type PdpSourcePrice = {
  currentPrice?: number;
  /** True when the variant's selling price is below its list (RRP) price — PRC-09. */
  isOnSale?: boolean;
  /** The original RRP. Present when `isOnSale` is true. */
  listPrice?: number;
  /**
   * True when `currentPrice` is the minimum across a set of variants rather than a single
   * definite price — e.g. a colour-only selection where sizes have different sale prices.
   * When true, Was/Now is suppressed: `currentPrice` is not a settled figure and showing a
   * definite Was/Now would misrepresent the product's pricing.
   */
  isRange?: boolean;
};

/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl. */
export type FormatPrice = (amount: number, currency: string) => string;

export type PdpProductInfo = {
  name: string;
  /** Active selling price (the "Now" price when on sale). */
  price: string;
  /** Original RRP. Present only when the product is on sale (PRC-09). */
  wasPrice?: string;
  description?: string;
  modelInfo?: string;
  careInstructions?: string;
  styleCode?: string;
  colour?: string;
  colourId?: string;
  environmentalNotes?: string;
  fabricComposition?: string;
  hsCode?: string;
  sizeFit?: string;
  styleId?: string;
  styleNumber?: string;
  stylingNotes?: string;
  tabDescription?: string;
  tabDetails?: string;
};

/**
 * @param product - The resolved product (variant when one is selected, master otherwise).
 * @param priceData - `getPriceData(...)`'s result, as ProductView computes it.
 * @param currency - The storefront's active currency code.
 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
 * @returns Props for the static-information components, or `null` while the product loads.
 */
/** One item in the `c_relatedSwatches` array resolved by the SCAPI hook (SFCC-708). */
export type RelatedSwatch = {
  masterProductID: string;
  colourValue: string;
  displayName: string;
  swatchImageURL: string;
};

export const selectPdpProductInfo = (
  product: PdpSourceProduct | undefined | null,
  priceData: PdpSourcePrice | undefined | null,
  currency: string,
  formatPrice: FormatPrice,
): PdpProductInfo | null => {
  if (!product?.name) return null;

  return {
    name: product.name,
    price: typeof priceData?.currentPrice === 'number' ? formatPrice(priceData.currentPrice, currency) : '',
    // PRC-09: expose the original RRP as wasPrice only when the item is genuinely on sale,
    // the price is a settled definite figure (not a range minimum), and the list price is a
    // real number. When `isRange` is true, `currentPrice` is the cheapest across a set of
    // variants — showing a definite Was/Now would misrepresent the price for other variants.
    // The Was/Now atoms branch on wasPrice's presence; when absent ZimmProductPrice renders
    // the standard single-price treatment.
    wasPrice:
      priceData?.isOnSale &&
      !priceData.isRange &&
      typeof priceData.currentPrice === 'number' &&
      typeof priceData.listPrice === 'number'
        ? formatPrice(priceData.listPrice, currency)
        : undefined,
    description: product.longDescription,
    modelInfo: product.c_modelFit,
    careInstructions: product.c_careInstructions,
    // The style code shoppers see is the *master* style number. `product.id` is the variant
    // SKU once a size is selected, so reading it would silently show a different value after
    // the first swatch click. Standard products have no master, and there `id` is correct.
    // Unchanged by the c_styleNumber addition below: Tim hasn't confirmed this should switch to
    // that attribute, only that c_styleNumber should be mapped and available.
    styleCode: product.master?.masterId ?? product.id,
    colour: product.c_color,
    colourId: product.c_colourId,
    environmentalNotes: product.c_environmentalNotes,
    fabricComposition: product.c_fabricComposition,
    hsCode: product.c_hsCode,
    sizeFit: product.c_sizeFit,
    styleId: product.c_styleId,
    styleNumber: product.c_styleNumber,
    stylingNotes: product.c_stylingNotes,
    tabDescription: product.c_tabDescription?.markup,
    tabDetails: product.c_tabDetails?.markup,
  };
};

/**
 * Maps SCAPI `c_relatedSwatches` items onto ZimmColourSwatchGroup-compatible swatch values.
 *
 * `urlBuilder` and `colourAttrId` are injected so this module stays dependency-free and
 * testable without a router context — the same pattern `selectPdpProductInfo` uses for
 * `formatPrice`.
 *
 * @param rawSwatches - The raw `c_relatedSwatches` array, pre-filtered by the SCAPI hook.
 * @param urlBuilder - Returns the base product URL for a given ID (e.g. `productUrlBuilder`).
 * @param colourAttrId - URL query-param key for the colour value (e.g. `'color'`).
 * @returns ZimmColourSwatchGroup-compatible swatch values with `forceReload: true`.
 */
export const buildRelatedSwatches = (
  rawSwatches: RelatedSwatch[],
  urlBuilder: (params: { id: string }) => string,
  colourAttrId: string,
) =>
  rawSwatches.map((item) => ({
    value: item.masterProductID,
    name: item.displayName,
    imageUrl: item.swatchImageURL,
    href: `${urlBuilder({ id: item.masterProductID })}?${colourAttrId}=${encodeURIComponent(item.colourValue)}`,
    orderable: true as const,
    forceReload: true as const,
  }));

