1	import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
2	import * as React from 'react';
3	import { renderToStaticMarkup } from 'react-dom/server';
4	import { renderHook, waitFor } from '@testing-library/react';
5	import { useCustomerType } from '@salesforce/commerce-sdk-react';
6	import { markProductViewed, RECENTLY_VIEWED_SESSION_KEY, useRecentlyViewedGate } from './useRecentlyViewedGate';
7	
8	vi.mock('@salesforce/commerce-sdk-react', () => ({
9	  useCustomerType: vi.fn(),
10	}));
11	
12	const mockUseCustomerType = vi.mocked(useCustomerType);
13	
14	function mockCustomerType(isRegistered: boolean): void {
15	  mockUseCustomerType.mockReturnValue({
16	    customerType: isRegistered ? 'registered' : 'guest',
17	    isGuest: !isRegistered,
18	    isRegistered,
19	    isExternal: false,
20	  });
21	}
22	
23	describe('markProductViewed', () => {
24	  beforeEach(() => {
25	    vi.clearAllMocks();
26	    window.sessionStorage.clear();
27	  });
28	
29	  afterEach(() => {
30	    vi.restoreAllMocks();
31	    window.sessionStorage.clear();
32	  });
33	
34	  test('sets the session flag', () => {
35	    markProductViewed();
36	    expect(window.sessionStorage.getItem(RECENTLY_VIEWED_SESSION_KEY)).not.toBeNull();
37	  });
38	
39	  test('does not throw, and leaves no flag set, when sessionStorage.setItem throws', () => {
40	    vi.spyOn(Storage.prototype, 'setItem').mockImplementation(() => {
41	      throw new Error('SecurityError: sessionStorage is not available (Safari private mode)');
42	    });
43	
44	    expect(() => markProductViewed()).not.toThrow();
45	
46	    vi.restoreAllMocks();
47	    expect(window.sessionStorage.getItem(RECENTLY_VIEWED_SESSION_KEY)).toBeNull();
48	  });
49	});
50	
51	describe('useRecentlyViewedGate', () => {
52	  beforeEach(() => {
53	    vi.clearAllMocks();
54	    window.sessionStorage.clear();
55	  });
56	
57	  afterEach(() => {
58	    vi.restoreAllMocks();
59	    window.sessionStorage.clear();
60	  });
61	
62	  test('no flag set, guest -> false', async () => {
63	    mockCustomerType(false);
64	
65	    const { result } = renderHook(() => useRecentlyViewedGate());
66	
67	    await waitFor(() => expect(result.current).toBe(false));
68	  });
69	
70	  test('flag set (via markProductViewed), guest -> true', async () => {
71	    mockCustomerType(false);
72	    markProductViewed();
73	
74	    const { result } = renderHook(() => useRecentlyViewedGate());
75	
76	    await waitFor(() => expect(result.current).toBe(true));
77	  });
78	
79	  test('no flag set, registered -> true', async () => {
80	    mockCustomerType(true);
81	
82	    const { result } = renderHook(() => useRecentlyViewedGate());
83	
84	    await waitFor(() => expect(result.current).toBe(true));
85	  });
86	
87	  test('sessionStorage.getItem throwing -> false, no uncaught exception', async () => {
88	    mockCustomerType(false);
89	    vi.spyOn(Storage.prototype, 'getItem').mockImplementation(() => {
90	      throw new Error('SecurityError: sessionStorage is not available (Safari private mode)');
91	    });
92	
93	    const { result } = renderHook(() => useRecentlyViewedGate());
94	
95	    await waitFor(() => expect(result.current).toBe(false));
96	  });
97	
98	  test('first render, before the effect has run -> false (SSR-safety)', () => {
