import { useProductSearch } from '@salesforce/commerce-sdk-react';
import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';
import { HOME_SHOP_PRODUCTS_CATEGORY_ID } from 'app/constants';

/**
 * 🔴 TEMPORARY — SFCC-83/84, stand-in for real Einstein data (2026-09-07, Marcel).
 *
 * Einstein is confirmed "Not Deployed" for every real Zimmermann site (BM Einstein Status
 * Dashboard, checked on 3 sandboxes) on top of two other independent, already-documented
 * blockers (DNT defaults ON app-wide; `EINSTEIN_API_SITE_ID` is a Salesforce demo tenant — see
 * the `project-einstein-siteid-investigation` memory). Real recommendations cannot be shown in
 * any environment today. Rather than block UI/wiring work on a cross-team platform-provisioning
 * timeline, this hook stands in for `useEinstein().getRecommendations` so the rail and Full
 * History page can be built, seen, and reviewed now.
 *
 * **This is the one seam that changes when real data becomes available** — first to a real
 * client-side view-history hook (tracking product IDs the shopper actually visits, discussed but
 * not yet built), later to real Einstein data. Every call site (`recommended-products/index.tsx`,
 * the PLP rail, and the Full History page container) reads only this hook's return shape, so
 * swapping its internals later does not require touching any of them.
 *
 * Sourced from a real, already-proven-live query — not invented: this is the *exact* `refine`/
 * `expand`/`perPricebook` shape `overrides/app/pages/home/index.tsx` already uses today to power
 * its own "Shop Products" section (`cgid=newarrivals`, the base SFCC reference catalog's
 * "New Arrivals" category — confirmed live on Zimmermann's own home page, not a guess). Reused
 * here because it's a real, working call already exercised in production, not because
 * "New Arrivals" has any actual relationship to what a shopper has viewed — it doesn't, and isn't
 * intended to. `limit: 12` is deliberately above every `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS`
 * threshold (2/3/5) so the See-Full-History CTA's "exceeds the visible rail width" branch is
 * exercisable at every breakpoint while this stand-in is in place.
 *
 * @returns `isLoading` and `hits` (real `ProductSearchHit[]`, `[]` while loading/on error) —
 *   the same shape `overrides/app/pages/product-list/productListCardMapper.ts` already maps.
 */
const TEMP_RECENTLY_VIEWED_LIMIT = 12;

export const useRecentlyViewedProducts = (): {
  isLoading: boolean;
  hits: ShopperSearchTypes.ProductSearchHit[];
} => {
  const { data, isLoading } = useProductSearch({
    parameters: {
      // SDK types `refine` as `string`, but the runtime accepts `string[]` — same documented
      // gotcha and cast as home/index.tsx's own identical call.
      refine: [`cgid=${HOME_SHOP_PRODUCTS_CATEGORY_ID as string}`, 'htype=master'] as unknown as string,
      expand: ['promotions', 'variations', 'prices', 'images', 'custom_properties'],
      perPricebook: true,
      allVariationProperties: true,
      allImages: true,
      limit: TEMP_RECENTLY_VIEWED_LIMIT,
    },
  });

  return { isLoading, hits: data?.hits ?? [] };
};

