/**
 * Deliberately minimal — this hook is a temporary stand-in (see its own docblock) with no
 * branching beyond the `data?.hits ?? []` fallback. Covers the one real behaviour worth proving:
 * hits pass through when present, and the fallback is `[]` (not `undefined`) so every consumer
 * can safely `.map` without an extra null check.
 */
import { describe, test, expect, vi } from 'vitest';
import { renderHook } from '@testing-library/react';
import { useProductSearch } from '@salesforce/commerce-sdk-react';
import { useRecentlyViewedProducts } from './useRecentlyViewedProducts';

