    mockUseProductSearch.mockReturnValue({ data: undefined, isLoading: true } as ReturnType<typeof useProductSearch>);

    const { result } = renderHook(() => useRecentlyViewedProducts());

    expect(result.current.hits).toEqual([]);
    expect(result.current.isLoading).toBe(true);
  });
});

