import type { SystemStyleObject } from '@chakra-ui/react';
import { breakpoints } from 'app/theme/foundation';

/**
 * Recipe for the Recently Viewed Full History grid organism (SFCC-84), build plan section B1.
 * Layout source: `Zimmermann_Designs` `3332:35655` (provisional — see this component's own
 * index.tsx docblock and B1's own plan.md section for the "everything here is provisional"
 * caveat). Title row from `3332:37131` (`PLP Bar desktop`, 1440x75, title left / count right).
 *
 * Column counts (2 / 3 / 4 across Mobile/Tablet/Desktop) are a reasonable placeholder, NOT read
 * off a confirmed per-breakpoint node — the supplied design only confirms "4-up desktop"
 * (`3332:35655`'s own grid). Flagged rather than guessed further per overrideStyling.md; revisit
 * once a Mobile/Tablet grid node is confirmed.
 *
 * Gap is `var(--zimm-scale-l)` (20px) — a placeholder value, same reasoning: no gap measurement
 * was supplied for this specific grid. Uses the registered token rather than a raw px so at
 * least the *value itself* stays traceable/adjustable in one place when a real one is confirmed.
 *
 * Parts: `container`, `header`, `itemCount`, `grid` — reconciled against index.tsx's own
 * `useMultiStyleConfig` reads by `ui-kits/recipeParts.test.ts`.
 */
const TABLET_UP_QUERY = `@media (min-width: ${breakpoints.md})`;
const DESKTOP_UP_QUERY = `@media (min-width: ${breakpoints.xl})`;

export const ZimmRecentlyViewedGrid = {
  parts: ['container', 'header', 'itemCount', 'grid'],

  baseStyle: (): Record<string, SystemStyleObject> => ({
    container: {
      width: '100%',
    },

    header: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      paddingBlock: 'var(--zimm-scale-l)',
    },

    itemCount: {
      color: 'var(--zimm-color-text-subtle)',
    },

    grid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(2, 1fr)',
      gap: 'var(--zimm-scale-l)',
      [TABLET_UP_QUERY]: {
        gridTemplateColumns: 'repeat(3, 1fr)',
      },
      [DESKTOP_UP_QUERY]: {
        gridTemplateColumns: 'repeat(4, 1fr)',
      },
    },
  }),
};

