      headingLevel: 'h3',
      href: `/product/${id}`,
      primaryImage: CARD_IMAGE,
      currentPrice: '$450.00',
    };
  });

/**
 * SFCC-84 — build plan section B1. See index.tsx's own module docblock for the full component
 * contract and zimmRecentlyViewedGrid.css.ts's own docblock for the provisional-design caveat and
 * the 2/3/4 responsive column geometry (resize the preview to see the steps).
