/**
 * Scoped per .claude/rules/testing.md: this component's OWN contract only — order preservation,
 * empty-input renders null, and the item-count label being a passthrough of whatever the
 * container computed (not re-derived here). `ZimmProductCard`'s own `plp`-variation internals
 * (badge, price, size chips, hover-swap) are already covered by zimmProductCard/index.test.tsx
 * and are deliberately NOT re-tested here — same "no duplicate coverage across layers" precedent
 * zimmRecentlyViewedRail/index.test.tsx already documents for its own composed child.
 *
 * `useMultiStyleConfig` is mocked with one flat object covering every part every composed
 * descendant reads — this grid's own 4 parts, plus every recipe a `plp`-variation `ZimmProductCard`
 * composes (ZimmProductCardMedia, ZimmProductCardContent, ZimmProductPrice, ZimmSizeChipGroup,
 * ZimmSizeChip). Some key names repeat across recipes (e.g. `container`/`root`) — harmless: this
 * mock returns the same flat object regardless of which recipe name asked for it, matching the
 * same precedent zimmRecentlyViewedRail/index.test.tsx and zimmProductCard/index.test.tsx already
 * establish; it proves this component's own contract, not any composed recipe's visual output.
 *
 * Icon mocks are the same known Vitest SVG-import issue documented in .claude/rules/testing.md
 * ("Known gap: ZimmIcon throws under Vitest") — copied verbatim from
 * zimmRecentlyViewedRail/index.test.tsx since this file sits at the identical
 * ui-kits/organisms/<name>/ depth.
 */
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import { ZimmRecentlyViewedGrid } from './index';
import type { ZimmProductCardProps } from '../zimmProductCard';

vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useMultiStyleConfig: () => ({
      // ZimmRecentlyViewedGrid (this component's own recipe).
      container: {},
      header: {},
      itemCount: {},
      grid: {},
      // ZimmProductCard.
      root: {},
      // ZimmProductCardMedia.
      scrollContainer: {},
      slide: {},
      image: {},
      hoverSwapBase: {},
      hoverSwapOverlay: {},
      badge: {},
      badgeLabel: {},
      close: {},
      carousel: {},
      arrowButton: {},
      indicatorWrapper: {},
      // ZimmProductCardContent.
      nameRow: {},
      nameLink: {},
      bagWrapper: {},
      bagButton: {},
      attributesRow: {},
      colourText: {},
      sizeText: {},
      priceWrapper: {},
      sizeChipWrapper: {},
      notifyMeButton: {},
      // ZimmProductPrice.
      wasPrice: {},
      nowPrice: {},
      // ZimmSizeChipGroup / ZimmSizeChip.
      radiogroup: {},
      oneSize: {},
      chip: {},
    }),
  };
});

vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
vi.mock('../../../icons', () => ({
  ChevronLeftIcon: () => null,
  ChevronRightIcon: () => null,
  CloseIcon: () => null,
}));

const wrap = (ui: React.ReactElement) =>
  render(
    <MemoryRouter>
      <IntlProvider locale="en" defaultLocale="en">
        {ui}
      </IntlProvider>
    </MemoryRouter>,
  );

const buildCard = (id: string): ZimmProductCardProps => ({
  id,
  variation: 'plp',
  name: `Product ${id}`,
  headingLevel: 'h3',
  href: `/product/${id}`,
  primaryImage: { src: `${id}.jpg`, alt: '' },
});

describe('ZimmRecentlyViewedGrid — order preservation', () => {
  /**
   * Fail-first requirement, same discipline as zimmRecentlyViewedRail's own order test: this
   * fixture's correct and reversed renderings are visibly different, so an assertion that only
   * checks "all ids present" would pass under a broken (reversed) implementation too.
   */
  test('renders cards in the exact order received, not sorted or reversed', () => {
    const cards = ['a', 'b', 'c', 'd', 'e'].map(buildCard);
    wrap(<ZimmRecentlyViewedGrid title="Recently Viewed" itemCountLabel="5 items" cards={cards} />);
    const renderedIds = screen.getAllByTestId('product-card').map((el) => el.getAttribute('data-product-id'));
    expect(renderedIds).toEqual(['a', 'b', 'c', 'd', 'e']);
  });

  test('renders every supplied card — unlike the rail, this page has no client-side cap', () => {
    const cards = Array.from({ length: 12 }, (_, i) => buildCard(`p${i}`));
    wrap(<ZimmRecentlyViewedGrid title="Recently Viewed" itemCountLabel="12 items" cards={cards} />);
    expect(screen.getAllByTestId('product-card')).toHaveLength(12);
  });
});

describe('ZimmRecentlyViewedGrid — empty state', () => {
  test('renders null when cards is empty', () => {
    const { container } = wrap(<ZimmRecentlyViewedGrid title="Recently Viewed" itemCountLabel="0 items" cards={[]} />);
    expect(container).toBeEmptyDOMElement();
  });
});

describe('ZimmRecentlyViewedGrid — item count label', () => {
  /**
   * This component renders whatever label the container computed — it does not derive or
   * validate the count itself (see index.tsx's own prop docblock). This test proves the
   * passthrough, not correctness of the count; a container that computes the wrong label would
   * not be caught here — that divergence is exactly what B2's own container-level test needs to
   * cover instead (testing.md: pick the cheapest layer that proves the behaviour).
   */
  test('renders itemCountLabel exactly as supplied, without recomputing it from cards.length', () => {
    const cards = ['a', 'b'].map(buildCard);
    wrap(<ZimmRecentlyViewedGrid title="Recently Viewed" itemCountLabel="a deliberately mismatched label" cards={cards} />);
    expect(screen.getByTestId('recently-viewed-grid-item-count')).toHaveTextContent(
      'a deliberately mismatched label',
    );
  });
});

