return (
  // 🔴 Fixed 2026-09-07 (Marcel flagged a Storybook discrepancy pass) — every spacing value
  // below was bare Chakra numeric shorthand (paddingX={4}, marginBottom={6}, etc.), which does
  // not resolve against this theme: `theme.space` is registered from the Zimmermann named-only
  // spacing scale (xs/s/m/l/xl/2xl/3xl — see theme/index.ts's own registration comment and
  // theme/foundation/spacing.ts), with no numeric 0-96 keys at all, unlike stock Chakra. Every
  // value below is now a real `var(--zimm-scale-*)` string per overrideStyling.md hierarchy
  // point 2. Horizontal padding matches the real, already-established page-container pattern
  // (`grid.containerPadding` in theme/foundation/gridSystem.ts) instead of an invented one.
  <Box
    data-testid="recently-viewed-page"
    paddingX={{ base: 'var(--zimm-scale-2xl)', xl: 'var(--zimm-scale-3xl)' }}
    paddingY="var(--zimm-scale-2xl)"
  >
    <Seo
      title={intl.formatMessage({ id: 'recently_viewed.seo.title', defaultMessage: 'Recently Viewed' })}
      description={intl.formatMessage({
        id: 'recently_viewed.seo.description',
        defaultMessage: 'Products you have recently viewed.',
      })}
    >
      <meta name="robots" content="noindex, nofollow" />
    </Seo>

    {!isLoading && cards.length === 0 && (
      <Box textAlign="center" paddingY="var(--zimm-scale-4xl)" data-testid="recently-viewed-empty-state">
        {/* textStyle, not Chakra's `size` — Heading has no entry in theme/components/index.ts,
            so `size="lg"` was silently falling through to stock Chakra typography, not this
            theme's registered scale. heading1 is a reasoned pick (page-level H1), not a
            confirmed Figma node — no node exists for this provisional page's title treatment. */}
        <Heading as="h1" textStyle="heading1" marginBottom="var(--zimm-scale-m)">
          {intl.formatMessage({ id: 'recently_viewed.empty.heading', defaultMessage: 'Recently Viewed' })}
        </Heading>
        <Text textStyle="body1" marginBottom="var(--zimm-scale-l)">
          {isRegistered
            ? intl.formatMessage({
                id: 'recently_viewed.empty.body.registered',
                defaultMessage: "You haven't viewed any products yet.",
              })
            : intl.formatMessage({
                id: 'recently_viewed.empty.body.guest',
                defaultMessage: "You haven't viewed any products yet. Sign in to see your history across devices.",
              })}
        </Text>
        <Button as={ChakraLink} href="/" variant="solid" marginRight={isRegistered ? undefined : 'var(--zimm-scale-m)'}>
          {intl.formatMessage({
            id: 'recently_viewed.empty.cta.continue_shopping',
            defaultMessage: 'Continue Shopping',
          })}
        </Button>
        {!isRegistered && (
          <Button as={ChakraLink} href="/login" variant="outline">
            {intl.formatMessage({ id: 'recently_viewed.empty.cta.sign_in', defaultMessage: 'Sign In' })}
          </Button>
        )}
      </Box>
    )}

    {(isLoading || cards.length > 0) && (
      <ZimmRecentlyViewedGrid
        title={
          <Heading as="h1" textStyle="heading1">
            {intl.formatMessage({ id: 'recently_viewed.heading', defaultMessage: 'Recently Viewed' })}
          </Heading>
        }
        itemCountLabel={itemCountLabel}
        cards={cards}
      />
    )}
  </Box>
);

