import React from 'react';
import { useIntl } from 'react-intl';
import { Box, Heading, Text, Button, Link as ChakraLink } from '@salesforce/retail-react-app/app/components/shared/ui';
import Seo from '@salesforce/retail-react-app/app/components/seo';
import { useCustomerType } from '@salesforce/commerce-sdk-react';
import { ZimmRecentlyViewedGrid } from '../../components/ui-kits/organisms/zimmRecentlyViewedGrid';
import type { ZimmProductCardProps } from '../../components/ui-kits/organisms/zimmProductCard';
// 🔴 TEMPORARY — see useRecentlyViewedProducts.ts's own docblock and recommended-products/
// index.tsx's identical note. This container reads the same seam A6 uses, so both surfaces swap
// together when real data becomes available.
import { useRecentlyViewedProducts } from '../../hooks/useRecentlyViewedProducts';
// Deliberate cross-page import — see recommended-products/index.tsx's identical note on this
// same import for the full reasoning; not repeated here.
import { selectProductListCard } from '../product-list/productListCardMapper';

/**
 * SFCC-84 — Recently Viewed Full History page (build plan section B2). Thin container: builds
 * `plp`-shaped cards and the item-count label, renders `ZimmRecentlyViewedGrid` (B1), owns all
 * copy. No data-fetching hook lives in the grid itself (components.md > Container/presentational).
 *
 * 🔶 Layout is built from a PROVISIONAL design source — see ZimmRecentlyViewedGrid's own module
 * docblock. Indexing is `noindex, nofollow` (decided, plan.md Open Question 4) — passed as a
 * `<Seo>` child, not the `noIndex` prop, which emits `noindex` only (no `nofollow`); see this
 * file's own Seo usage below.
 *
 * Empty state modelled on the house pattern (`EmptyCart`/`EmptySearchResults`/`empty-wishlist`):
 * heading + isRegistered-branched copy + CTA, never nothing. Final copy not yet confirmed by
 * Jasmijn — provisional English strings below, not a build blocker (plan.md B2).
 */
const RecentlyViewed = () => {
  const intl = useIntl();
  const { isRegistered } = useCustomerType();
  // 🔴 TEMPORARY — see this file's own module docblock.
  const { hits, isLoading } = useRecentlyViewedProducts();
  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });

  const cards: ZimmProductCardProps[] = hits
    .map((hit) => selectProductListCard(hit, formatPrice))
    .filter((card): card is NonNullable<typeof card> => card !== null);

  const itemCountLabel = intl.formatMessage(
    {
      id: 'recently_viewed.label.item_count',
      defaultMessage: '{count, plural, one {# item} other {# items}}',
    },
    { count: cards.length },
  );

  return (
    <Box data-testid="recently-viewed-page" paddingX={{ base: 4, md: 8, lg: 0 }} paddingY={8}>
      <Seo
        title={intl.formatMessage({ id: 'recently_viewed.seo.title', defaultMessage: 'Recently Viewed' })}
        description={intl.formatMessage({
          id: 'recently_viewed.seo.description',
          defaultMessage: 'Products you have recently viewed.',
        })}
      >
        <meta name="robots" content="noindex, nofollow" />
      </Seo>

      {!isLoading && cards.length === 0 && (
        <Box textAlign="center" paddingY={16} data-testid="recently-viewed-empty-state">
          <Heading as="h1" size="lg" marginBottom={4}>
            {intl.formatMessage({ id: 'recently_viewed.empty.heading', defaultMessage: 'Recently Viewed' })}
          </Heading>
          <Text marginBottom={6}>
            {isRegistered
              ? intl.formatMessage({
                  id: 'recently_viewed.empty.body.registered',
                  defaultMessage: "You haven't viewed any products yet.",
                })
              : intl.formatMessage({
                  id: 'recently_viewed.empty.body.guest',
                  defaultMessage: "You haven't viewed any products yet. Sign in to see your history across devices.",
                })}
          </Text>
          <Button as={ChakraLink} href="/" variant="solid" marginRight={isRegistered ? 0 : 4}>
            {intl.formatMessage({
              id: 'recently_viewed.empty.cta.continue_shopping',
              defaultMessage: 'Continue Shopping',
            })}
          </Button>
          {!isRegistered && (
            <Button as={ChakraLink} href="/login" variant="outline">
              {intl.formatMessage({ id: 'recently_viewed.empty.cta.sign_in', defaultMessage: 'Sign In' })}
            </Button>
          )}
        </Box>
      )}

      {(isLoading || cards.length > 0) && (
        <ZimmRecentlyViewedGrid
          title={
            <Heading as="h1" size="lg">
              {intl.formatMessage({ id: 'recently_viewed.heading', defaultMessage: 'Recently Viewed' })}
            </Heading>
          }
          itemCountLabel={itemCountLabel}
          cards={cards}
        />
      )}
    </Box>
  );
};

RecentlyViewed.getTemplateName = () => 'recently-viewed';

export default RecentlyViewed;

