import React from 'react';
import type { ReactNode } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmProductCard } from '../zimmProductCard';
import type { ZimmProductCardProps } from '../zimmProductCard';

export type ZimmRecentlyViewedGridProps = {
  /** Rendered as-is — this component owns no copy/intl, matching ZimmRecentlyViewedRail's own
   *  split (the container owns copy). */
  title: ReactNode;
  /** Rendered as-is, next to the title. The container computes this from `cards.length` — this
   *  component does not derive or validate the count itself (see index.test.tsx: a divergence
   *  between this and the rendered tile count is a container bug, not something this component
   *  can catch). */
  itemCountLabel: ReactNode;
  /** Rendered in the exact order received — no sorting/reordering happens here. Unlike
   *  ZimmRecentlyViewedRail, there is no client-side cap: this page IS the overflow destination,
   *  so every card the container supplies is rendered. */
  cards: readonly ZimmProductCardProps[];
};

const ZIMM_RECENTLY_VIEWED_GRID_RECIPE = 'ZimmRecentlyViewedGrid';

/**
 * SFCC-84 — the Recently Viewed Full History page's product grid (build plan section B1).
 * Purely presentational: data arrives as props, no data-fetching, no useEinstein, no useIntl —
 * same container/presentational split as ZimmRecentlyViewedRail (components.md). The container
 * (B2) builds `cards` and computes `itemCountLabel`.
 *
 * 🔶 Built from a PROVISIONAL design source (`Zimmermann_Designs` `3332:35655`/`3332:37131`), not
 * a confirmed PDP Recently Viewed node — see zimmRecentlyViewedGrid.css.ts's own docblock. Flagged
 * here and in the PR body per Marcel's precedence rule (2026-09-04): a provisional source is
 * still built, not skipped, but never presented as design-confirmed.
 *
 * Cards render at `variation: 'plp'` (badge, hover-swap, size chips, was/now pricing when
 * available) — the container is responsible for supplying already-`plp`-shaped card props, this
 * component does not set or override `variation` itself, unlike ZimmRecentlyViewedRail (which
 * forces `recentlyViewed`). That asymmetry is deliberate: this grid has no single variation of
 * its own to enforce, it renders whatever shape the container already decided on.
 */
export const ZimmRecentlyViewedGrid = ({ title, itemCountLabel, cards }: ZimmRecentlyViewedGridProps) => {
  const styles = useMultiStyleConfig(ZIMM_RECENTLY_VIEWED_GRID_RECIPE, {});

  if (cards.length === 0) {
    return null;
  }

  return (
    <chakra.div __css={styles.container} data-testid="recently-viewed-grid">
      <chakra.div __css={styles.header}>
        {title}
        <chakra.span __css={styles.itemCount} data-testid="recently-viewed-grid-item-count">
          {itemCountLabel}
        </chakra.span>
      </chakra.div>
      <chakra.div __css={styles.grid}>
        {cards.map((card) => (
          <ZimmProductCard key={card.id} {...card} />
        ))}
      </chakra.div>
    </chakra.div>
  );
};

