14	import { selectProductListCard } from '../product-list/productListCardMapper';
15	
16	/**
17	 * SFCC-84 — Recently Viewed Full History page (build plan section B2). Thin container: builds
18	 * `plp`-shaped cards and the item-count label, renders `ZimmRecentlyViewedGrid` (B1), owns all
19	 * copy. No data-fetching hook lives in the grid itself (components.md > Container/presentational).
20	 *
21	 * 🔶 Layout is built from a PROVISIONAL design source — see ZimmRecentlyViewedGrid's own module
22	 * docblock. Indexing is `noindex, nofollow` (decided, plan.md Open Question 4) — passed as a
23	 * `<Seo>` child, not the `noIndex` prop, which emits `noindex` only (no `nofollow`); see this
24	 * file's own Seo usage below.
25	 *
26	 * Empty state modelled on the house pattern (`EmptyCart`/`EmptySearchResults`/`empty-wishlist`):
27	 * heading + isRegistered-branched copy + CTA, never nothing. Final copy not yet confirmed by
28	 * Jasmijn — provisional English strings below, not a build blocker (plan.md B2).
29	 */
30	const RecentlyViewed = () => {
31	  const intl = useIntl();
32	  const { isRegistered } = useCustomerType();
33	  // 🔴 TEMPORARY — see this file's own module docblock.
34	  const { hits, isLoading } = useRecentlyViewedProducts();
35	  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });
36	
37	  const cards: ZimmProductCardProps[] = hits
38	    .map((hit) => selectProductListCard(hit, formatPrice))
39	    .filter((card): card is NonNullable<typeof card> => card !== null);
40	
41	  const itemCountLabel = intl.formatMessage(
42	    {
43	      id: 'recently_viewed.label.item_count',
44	      defaultMessage: '{count, plural, one {# item} other {# items}}',
45	    },
46	    { count: cards.length },
47	  );
48	
49	  return (
50	    // 🔴 Fixed 2026-09-07 (Marcel flagged a Storybook discrepancy pass) — every spacing value
51	    // below was bare Chakra numeric shorthand (paddingX={4}, marginBottom={6}, etc.), which does
52	    // not resolve against this theme: `theme.space` is registered from the Zimmermann named-only
53	    // spacing scale (xs/s/m/l/xl/2xl/3xl — see theme/index.ts's own registration comment and
54	    // theme/foundation/spacing.ts), with no numeric 0-96 keys at all, unlike stock Chakra. Every
55	    // value below is now a real `var(--zimm-scale-*)` string per overrideStyling.md hierarchy
56	    // point 2. Horizontal padding matches the real, already-established page-container pattern
57	    // (`grid.containerPadding` in theme/foundation/gridSystem.ts) instead of an invented one.
58	    <Box
59	      data-testid="recently-viewed-page"
60	      paddingX={{ base: 'var(--zimm-scale-2xl)', xl: 'var(--zimm-scale-3xl)' }}
61	      paddingY="var(--zimm-scale-2xl)"
62	    >
63	      <Seo
64	        title={intl.formatMessage({ id: 'recently_viewed.seo.title', defaultMessage: 'Recently Viewed' })}
65	        description={intl.formatMessage({
66	          id: 'recently_viewed.seo.description',
67	          defaultMessage: 'Products you have recently viewed.',
68	        })}
69	      >
70	        <meta name="robots" content="noindex, nofollow" />
71	      </Seo>
72	
73	      {!isLoading && cards.length === 0 && (
74	        <Box textAlign="center" paddingY="var(--zimm-scale-4xl)" data-testid="recently-viewed-empty-state">
75	          {/* textStyle, not Chakra's `size` — Heading has no entry in theme/components/index.ts,
76	              so `size="lg"` was silently falling through to stock Chakra typography, not this
77	              theme's registered scale. heading1 is a reasoned pick (page-level H1), not a
78	              confirmed Figma node — no node exists for this provisional page's title treatment. */}
79	          <Heading as="h1" textStyle="heading1" marginBottom="var(--zimm-scale-m)">
80	            {intl.formatMessage({ id: 'recently_viewed.empty.heading', defaultMessage: 'Recently Viewed' })}
81	          </Heading>
82	          <Text textStyle="body1" marginBottom="var(--zimm-scale-l)">
83	            {isRegistered
84	              ? intl.formatMessage({
85	                  id: 'recently_viewed.empty.body.registered',
86	                  defaultMessage: "You haven't viewed any products yet.",
87	                })
88	              : intl.formatMessage({
89	                  id: 'recently_viewed.empty.body.guest',
90	                  defaultMessage: "You haven't viewed any products yet. Sign in to see your history across devices.",
91	                })}
92	          </Text>
93	          <Button
94	            as={ChakraLink}
95	            href="/"
96	            variant="solid"
97	            marginRight={isRegistered ? undefined : 'var(--zimm-scale-m)'}
98	          >
99	            {intl.formatMessage({
100	              id: 'recently_viewed.empty.cta.continue_shopping',
101	              defaultMessage: 'Continue Shopping',
102	            })}
103	          </Button>
104	          {!isRegistered && (
105	            <Button as={ChakraLink} href="/login" variant="outline">
106	              {intl.formatMessage({ id: 'recently_viewed.empty.cta.sign_in', defaultMessage: 'Sign In' })}
107	            </Button>
108	          )}
109	        </Box>
110	      )}
111	
112	      {(isLoading || cards.length > 0) && (
113	        <ZimmRecentlyViewedGrid
114	          title={
115	            <Heading as="h1" textStyle="heading1">
116	              {intl.formatMessage({ id: 'recently_viewed.heading', defaultMessage: 'Recently Viewed' })}
117	            </Heading>
118	          }
119	          itemCountLabel={itemCountLabel}
120	          cards={cards}
121	        />
122	      )}
123	    </Box>
124	  );
125	};
126	
127	RecentlyViewed.getTemplateName = () => 'recently-viewed';
128	
129	export default RecentlyViewed;

