import { chromium } from 'playwright';

const BASE = 'http://localhost:3000';
const OUT = '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/3062b85f-ee32-4350-ae00-30fe2f595ef5/scratchpad';
const PRODUCT_IDS = ['8637DS241', 'ZWNEWPRD03', 'ZWNEWPRD04'];

const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1440, height: 1200 } });
const page = await context.newPage();

const errors = [];
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(msg.text());
});
page.on('pageerror', (err) => errors.push(String(err)));

// Build real view history by visiting multiple real PDPs in sequence, same browser context.
for (const id of PRODUCT_IDS) {
  await page.goto(`${BASE}/product/${id}`, { waitUntil: 'networkidle', timeout: 30000 });
  await page.waitForTimeout(1500);
}

// Check what's actually in storage right now, and whether the LAST-visited product
// (currently being viewed) shows up in its own rail.
const storageState = await page.evaluate(() => ({
  sessionStorage: { ...sessionStorage },
  localStorage: { ...localStorage },
}));
console.log('STORAGE STATE:', JSON.stringify(storageState, null, 2));

// Screenshot the current PDP (last visited product) - check for self-inclusion + gallery/full-width interaction.
const railOnPdp = await page.locator('[data-testid="recently-viewed-rail"]').count();
console.log('Rail present on PDP:', railOnPdp);
if (railOnPdp > 0) {
  const cardIds = await page.locator('[data-testid="recently-viewed-rail"] [data-product-id]').allTextContents();
  const cardIdAttrs = await page.locator('[data-testid="recently-viewed-rail"] [data-product-id]').evaluateAll((els) =>
    els.map((el) => el.getAttribute('data-product-id')),
  );
  console.log('Card product IDs on PDP rail:', cardIdAttrs);
  console.log('Current PDP product ID (last visited):', PRODUCT_IDS[PRODUCT_IDS.length - 1]);
}
await page.screenshot({ path: `${OUT}/live-pdp-with-rail.png`, fullPage: true });

// Cart
await page.goto(`${BASE}/cart`, { waitUntil: 'networkidle', timeout: 30000 });
await page.waitForTimeout(1000);
const railOnCart = await page.locator('[data-testid="recently-viewed-rail"]').count();
console.log('Rail present on Cart:', railOnCart);
await page.screenshot({ path: `${OUT}/live-cart-with-rail.png`, fullPage: true });

// PLP
await page.goto(`${BASE}/search?q=dress`, { waitUntil: 'networkidle', timeout: 30000 });
await page.waitForTimeout(1000);
const railOnPlp = await page.locator('[data-testid="recently-viewed-rail"]').count();
console.log('Rail present on PLP:', railOnPlp);
await page.screenshot({ path: `${OUT}/live-plp-with-rail.png`, fullPage: true });

// Full History page
await page.goto(`${BASE}/recently-viewed`, { waitUntil: 'networkidle', timeout: 30000 });
await page.waitForTimeout(1000);
const gridPresent = await page.locator('[data-testid="recently-viewed-grid"]').count();
console.log('Grid present on Full History page:', gridPresent);
await page.screenshot({ path: `${OUT}/live-full-history-with-grid.png`, fullPage: true });

console.log('CONSOLE/PAGE ERRORS CAPTURED:', errors.length);
if (errors.length) console.log(errors.slice(0, 20).join('\n---\n'));

await browser.close();

