let capturedProduct = null;
page.on('response', async (res) => {
  const url = res.url();
  if (url.includes('/product/') && url.includes('ocapi') === false && (url.includes('products') || url.includes('4673TS251'))) {
    try {
      const json = await res.json();
      if (json && (json.id === '4673TS251' || (Array.isArray(json.data) && json.data.some((p) => p.id === '4673TS251')))) {
        capturedProduct = json.id === '4673TS251' ? json : json.data.find((p) => p.id === '4673TS251');
      }
    } catch {}
  }
});

for (const id of ['4673TS251', '8637DS241']) {
  await page.goto(`http://localhost:3000/product/${id}`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(1500);
}

if (capturedProduct) {
  console.log('imageGroups for 4673TS251:');
  console.log(JSON.stringify(capturedProduct.imageGroups, null, 2));
} else {
  console.log('Could not capture product response directly — dumping all image-bearing responses instead');
}
await browser.close();
