export const CUSTOM_HOME_TITLE = '🎉 Hello Zimmermann!';

// SFCC-83 — ZimmRecentlyViewedRail's client-side cap. Matches the Desktop Figma composition
// (`40000307:12444`, 5 bare product images across the rail's `group` child) — the Einstein
// recommender endpoint this rail's data ultimately comes from does not itself honour a requested
// `limit`, so the cap has to be enforced client-side, in the rail component itself, not assumed
// true of the input array.
export const RECENTLY_VIEWED_RAIL_MAX_ITEMS = 5;

// SFCC-83 — interim history-storage cap for `useRecentlyViewedHistory` (build plan §2, "Interim
// data source"). Set to 24, matching the Shopper Products `getProducts` endpoint's own hard
// per-request ID limit that `recentlyViewedProductFetch.ts` must cap to (confirmed directly in
// the SDK's own doc comment — see that file): storing more IDs than a single fetch can ever
// resolve would never produce a displayable card. Confirmed with Marcel (2026-09-08): this
// supersedes the build plan's own originally-closed Open Question 17 (`= 500`) — that number
// predated the 24-ID fetch-limit discovery, so `24` is the final value, not a pending question.
export const RECENTLY_VIEWED_HISTORY_MAX_STORED = 24;

// SFCC-84 — the Recently Viewed Full History page's own route path (build plan §B2). Named here,
// not just inlined in routes.tsx, so the "See Full History" link (RecommendedProducts' own
// `seeAllHref`, build plan §B3) has one canonical value to import rather than a second hand-typed
// copy of this same string.
export const RECENTLY_VIEWED_ROUTE = '/recently-viewed';

// SFCC-83/84 — per-breakpoint "how many cards actually fit on screen without scrolling" for the
// See-Full-History trigger (build plan §B3, Open Question 1 reopened 2026-09-07). Deliberately
// distinct from RECENTLY_VIEWED_RAIL_MAX_ITEMS above, which only ever governs the rail's *render*
// cap (5, regardless of breakpoint) — this constant answers a different question ("does the
// shopper have more than fits in view right now"), matching the AC's own "exceeds the visible
// rail width" wording, which is genuinely viewport-relative, not a flat count. Values match
// zimmRecentlyViewedRail.css.ts's own confirmed per-breakpoint visible-card-count table (Mobile
// 201px cards × 2 = 402px full-bleed, Tablet 256px × 3 = 768px, Desktop 288px × 5 = 1440px) —
// restated here as counts, not re-measured. Keyed on Chakra's own breakpoint names for direct use
// with `useBreakpointValue`, matching the same `md`/`xl` steps the rail's own recipe uses
// (`breakpoints.md`/`breakpoints.xl`), not a separate breakpoint set.
export const RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS = { base: 2, md: 3, xl: 5 } as const;

export {
  MAX_CACHE_AGE,
  STALE_WHILE_REVALIDATE,
  HOME_SHOP_PRODUCTS_CATEGORY_ID,
  HOME_SHOP_PRODUCTS_LIMIT,
} from '@salesforce/retail-react-app/app/constants';

export * from '@salesforce/retail-react-app/app/constants';

