      sendViewReco: vi.fn(),
    });
    mockUseRecentlyViewedHistory.mockReturnValue({
      hasRecentlyViewed: false,
      recentlyViewedIds: [],
      markProductViewed: vi.fn(),
    });
    mockUseRecentlyViewedProductFetch.mockReturnValue({ products: [], isLoading: false });

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED });

    // Neither branch's component rendered — the component itself returns `null` here. Not
    // asserted via `container.toBeEmptyDOMElement()`: ChakraProvider always injects its own
    // internal `<span id="__chakra_env">` marker regardless of what this component renders, so
    // an empty-container check would be asserting on Chakra's own internals, not this
    // component's contract.
    expect(screen.queryByTestId('zimm-recently-viewed-rail-stub')).not.toBeInTheDocument();
    expect(screen.queryByTestId('product-scroller-stub')).not.toBeInTheDocument();
    expect(mockSelectRecentlyViewedCard).not.toHaveBeenCalled();
  });

  test('dead-check reordering (bug fix #3): recommendations empty/undefined from useEinstein() + hasRecentlyViewed true still renders the rail', () => {
    // This is the exact regression fix #3 exists to catch. Before the reorder, the pre-existing
    // dead-check (`!isLoading && (!recommendations || recommendations.length < 1)`) ran BEFORE
    // the Recently-Viewed branch below it and would have returned `null` unconditionally here —
    // `recommendations` is `undefined` (exercising the check's `!recommendations` clause) and
    // never populated for this branch regardless, so this would fire whether `recommendations`
    // ends up `undefined` or (as in real production) an unpopulated `[]` — regardless of
    // `hasRecentlyViewed`. If the branch is ever moved back below that check, this test fails.
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: undefined,
      getZoneRecommendations: vi.fn(),
      getRecommendations: vi.fn(),
      sendClickReco: vi.fn(),
      sendViewReco: vi.fn(),
    });
    mockUseRecentlyViewedHistory.mockReturnValue({
      hasRecentlyViewed: true,
      recentlyViewedIds: ['rec-1'],
      markProductViewed: vi.fn(),
    });
    mockUseRecentlyViewedProductFetch.mockReturnValue({
      products: [mockRecentlyViewedProducts[0]],
      isLoading: false,
    });
    mockSelectRecentlyViewedCard.mockReturnValue({
      id: 'rec-1',
      href: '/product/rec-1',
      name: 'Product One',
      primaryImage: { src: 'https://example.test/image.jpg', alt: 'Product One' },
      currentPrice: undefined,
    });

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED });

    expect(screen.getByTestId('zimm-recently-viewed-rail-stub')).toBeInTheDocument();
    expect(screen.queryByTestId('product-scroller-stub')).not.toBeInTheDocument();
  });

  // Build plan §B3 — the See-Full-History link. jsdom resolves `useBreakpointValue` to its `base`
  // value (no real viewport), so these fixtures are sized against `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base`
  // (2) rather than asserting anything about actual breakpoint switching — that's Chakra's own
  // concern, not this component's. What this component owns is purely "count vs threshold", which
  // is breakpoint-agnostic to test.
  test('See-Full-History link appears when available cards exceed the visible count at this breakpoint', () => {
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: [],
      getZoneRecommendations: vi.fn(),
      getRecommendations: vi.fn(),
      sendClickReco: vi.fn(),
      sendViewReco: vi.fn(),
    });
    const ids = ['rec-1', 'rec-2', 'rec-3'];
    mockUseRecentlyViewedHistory.mockReturnValue({
      hasRecentlyViewed: true,
      recentlyViewedIds: ids,
      markProductViewed: vi.fn(),
    });
    mockUseRecentlyViewedProductFetch.mockReturnValue({
      products: ids.map((id) => ({ id, name: `Product ${id}` } as RecentlyViewedProduct)),
      isLoading: false,
    });
    mockSelectRecentlyViewedCard.mockImplementation((product) => ({
      id: product?.id ?? '',
      href: `/product/${product?.id ?? ''}`,
      name: product?.name ?? '',
      primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
      currentPrice: undefined,
    }));

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED });

    const railProps = mockZimmRecentlyViewedRail.mock.calls[0][0];
    // Site/locale-prefixed via useMultiSite's buildUrl (mocked above to a non-default `/en-GB`
    // prefix) — the rail itself must never build this prefix (build plan §B3's own pass criterion).
    expect(railProps.seeAllHref).toBe('/en-GB/recently-viewed');
    expect(railProps.seeAllLabel).toBe('See Full History');
  });

  test('See-Full-History link is absent when available cards do not exceed the visible count at this breakpoint', () => {
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: [],
      getZoneRecommendations: vi.fn(),
      getRecommendations: vi.fn(),
      sendClickReco: vi.fn(),
      sendViewReco: vi.fn(),
    });
    const ids = ['rec-1', 'rec-2'];
    mockUseRecentlyViewedHistory.mockReturnValue({
      hasRecentlyViewed: true,
      recentlyViewedIds: ids,
      markProductViewed: vi.fn(),
    });
    mockUseRecentlyViewedProductFetch.mockReturnValue({
      products: ids.map((id) => ({ id, name: `Product ${id}` } as RecentlyViewedProduct)),
      isLoading: false,
    });
    mockSelectRecentlyViewedCard.mockImplementation((product) => ({
      id: product?.id ?? '',
      href: `/product/${product?.id ?? ''}`,
      name: product?.name ?? '',
      primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
      currentPrice: undefined,
    }));

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED });

    const railProps = mockZimmRecentlyViewedRail.mock.calls[0][0];
    expect(railProps.seeAllHref).toBeUndefined();
    expect(railProps.seeAllLabel).toBeUndefined();
  });
});

