import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import { RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS } from 'app/constants';
import { ZimmRecentlyViewedRail } from './index';
import type { ZimmProductCardProps } from '../zimmProductCard';

// jsdom has no matchMedia implementation, and this component's own `useBreakpointValue` call
// (RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS, added 2026-09-08 for the hard per-breakpoint cap) needs
// one — a per-file polyfill, not a change to the frozen vitest.setup.ts (Tier 1), matching the
// identical, already-established precedent at drawer-menu/index.test.tsx and
// recommended-products/index.test.tsx (Chakra's own useBreakpointValue usage). `matches: false`
// unconditionally is what makes useBreakpointValue resolve to its `base` value in this
// environment — jsdom has no real viewport, so proving the `md`/`xl` cases genuinely respond to a
// real breakpoint is Storybook's job (a real browser), not this file's — same "that's Chakra's
// own concern, not this component's" reasoning recommended-products/index.test.tsx already
// documents for the identical situation.
beforeEach(() => {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    value: vi.fn().mockImplementation((query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addListener: vi.fn(),
      removeListener: vi.fn(),
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      dispatchEvent: vi.fn(),
    })),
  });
});

