// own concern, not this component's" reasoning recommended-products/index.test.tsx already
// documents for the identical situation.
beforeEach(() => {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    value: vi.fn().mockImplementation((query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addListener: vi.fn(),
      removeListener: vi.fn(),
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      dispatchEvent: vi.fn(),
    })),
  });
});

vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useMultiStyleConfig: () => ({
      // ZimmRecentlyViewedRail (this component's own recipe).
      container: {},
      header: {},
      seeAllLink: {},
      group: {},
      card: {},
      // ZimmProductCard.
      root: {},
      // ZimmProductCardMedia.
      scrollContainer: {},
      slide: {},
      image: {},
      hoverSwapBase: {},
      hoverSwapOverlay: {},
      badge: {},
      badgeLabel: {},
      close: {},
      carousel: {},
      arrowButton: {},
      indicatorWrapper: {},
    }),
  };
});

