  render(
    <MemoryRouter>
      <IntlProvider locale="en" defaultLocale="en">
        {ui}
      </IntlProvider>
    </MemoryRouter>,
  );

const buildCard = (id: string): ZimmProductCardProps => ({
  id,
  variation: 'recentlyViewed',
  name: `Product ${id}`,
  headingLevel: 'h3',
  href: `/product/${id}`,
  primaryImage: { src: `${id}.jpg`, alt: '' },
});

describe('ZimmRecentlyViewedRail — cap (RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS, hard per-breakpoint cap)', () => {
  // jsdom's matchMedia polyfill above always resolves useBreakpointValue to `base` (2) — this
  // describe block therefore only proves the `base` case is a genuine hard cap (more supplied
  // than the cap never renders more than the cap). The `md`/`xl` cases resolving correctly to a
  // real browser viewport is proven in Storybook (real matchMedia), not here.
  test('renders at most RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base cards when more are supplied', () => {
    const cards = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'].map(buildCard);
    wrap(<ZimmRecentlyViewedRail title="Recently Viewed" cards={cards} />);
    expect(screen.getAllByTestId('product-card')).toHaveLength(RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base);
  });

  test('renders exactly the number of cards supplied when under the cap', () => {
    const cards = ['a'].map(buildCard);
    wrap(<ZimmRecentlyViewedRail title="Recently Viewed" cards={cards} />);
    expect(screen.getAllByTestId('product-card')).toHaveLength(1);
  });
});

describe('ZimmRecentlyViewedRail — order preservation (AC 2: most-recent-first, left to right)', () => {
  /**
   * Fixture kept at exactly RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base (2) cards, not more —
   * jsdom's matchMedia polyfill above resolves the cap to `base`, so a fixture larger than that
   * would have its tail truncated by the (correct, separately-tested) cap before order could ever
   * be observed on the truncated entries, muddying what this test is actually proving.
