/**
 * Same 8-card fixture as `Default` (reused, not re-built — same "split for `play`-function
 * clarity" relationship `WithSeeAllLink`/`SeeAllLinkKeyboardFocus` above already establish),
 * with a `play` function attached to turn the cap into an automated assertion instead of a
 * manual visual count.
 *
 * **What this actually proves, precisely — read before trusting the number below.**
 * `@storybook/test-runner`'s Playwright browser launches at a fixed viewport with no per-story
 * override available in this project (see meta docblock above) — this `play` function therefore
 * only ever exercises whichever ONE of the three tiers that fixed viewport happens to fall into,
 * not all three. Empirically confirmed by running `test-storybook --ci` against the real running
 * local instance (2026-09-08): the default Playwright viewport here is exactly 1280px wide, which
 * satisfies `useBreakpointValue`'s `xl` query (`min-width: 80em` = 1280px, inclusive) — so this
 * resolves to the Desktop tier (cap 5), confirmed by first running this assertion at the OLD
 * flat cap's value (5) and observing it pass, then re-running with a deliberately wrong value (4)
 * and observing it fail with "Received: 5" — not assumed from Playwright's documented default
 * alone. If `@storybook/test-runner`'s own default viewport ever changes, or if
 * `@storybook/addon-viewport` is added later and starts applying a different default globally,
 * this number would need re-confirming the same way — it is not derived from
 * `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.xl` in code, precisely so a drift between the two isn't
 * silently masked by both sides changing together.
 */
export const OverCap: Story = {
  args: Default.args,
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const cards = await canvas.findAllByTestId('product-card');
    await expect(cards).toHaveLength(5);
  },
};

