import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
await page.goto(
  'http://localhost:6006/iframe.html?id=commerce-zimmrecentlyviewedrail--see-all-link-keyboard-focus&viewMode=story',
);
await page.waitForTimeout(1000); // let the story's own play() (which already Tabs once) finish
await page.screenshot({ path: '.tmp-focus-screenshot.png', fullPage: true });
const link = page.locator('a', { hasText: 'See Full History' });
await link.screenshot({ path: '.tmp-focus-zoom.png' });

const result = await page.evaluate(() => {
  const el = document.activeElement;
  if (!el) return { error: 'no activeElement' };
  const cs = getComputedStyle(el);
  const rect = el.getBoundingClientRect();
  return {
    tag: el.tagName,
    text: el.textContent,
    outline: cs.outline,
    outlineWidth: cs.outlineWidth,
    outlineStyle: cs.outlineStyle,
    outlineColor: cs.outlineColor,
    outlineOffset: cs.outlineOffset,
    boxShadow: cs.boxShadow,
    rect: { x: rect.x, y: rect.y, width: rect.width, height: rect.height },
    parentOverflow: el.parentElement ? getComputedStyle(el.parentElement).overflow : null,
    grandparentOverflow: el.parentElement?.parentElement
      ? getComputedStyle(el.parentElement.parentElement).overflow
      : null,
    cssVarFocusRing: getComputedStyle(document.documentElement).getPropertyValue('--zimm-focus-ring'),
    cssVarFocusRingOffset: getComputedStyle(document.documentElement).getPropertyValue(
      '--zimm-focus-ring-offset-default',
    ),
  };
});

console.log(JSON.stringify(result, null, 2));
await browser.close();

